-- 剥洋葱算出的安全清怪顺序（离线）。运行时可按 new_ord 顺序拉。
CREATE TABLE IF NOT EXISTS `ai_playerbot_pull_order` (
  `map` smallint unsigned NOT NULL,
  `new_ord` smallint unsigned NOT NULL,
  `old_ord` smallint unsigned NOT NULL,
  `pred_adds` smallint unsigned NOT NULL DEFAULT 0,
  `calc_at` datetime NOT NULL,
  `source` varchar(32) NOT NULL DEFAULT 'peel',
  PRIMARY KEY (`map`,`new_ord`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `ai_playerbot_pull_order` WHERE `map` IN (540,542,543,545,546,547,552,553,555,556,557,558);

